# Let's test with patches in different corners to find the target class
# Create images with white square patches (3x3) in each corner, 1 pixel in from edges

def create_patch_images(patch_type="white", patch_size=3, corner="tl"):
    """Create images with patches in specified corner"""
    images = x_clean[:100].clone().float()  # Use first 100 images

    # Corner positions: 1 pixel in from edges
    if corner == "tl":  # top-left
        h_start, w_start = 1, 1
    elif corner == "tr":  # top-right
        h_start, w_start = 1, 32 - 1 - patch_size
    elif corner == "bl":  # bottom-left
        h_start, w_start = 32 - 1 - patch_size, 1
    elif corner == "br":  # bottom-right
        h_start, w_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    if patch_type == "white":
        patch_val = 255
    elif patch_type == "black":
        patch_val = 0
    elif patch_type == "checkerboard":
        patch_val = None  # will fill manually
    elif patch_type == "random":
        patch_val = "random"

    for i in range(images.shape[0]):
        if patch_type == "checkerboard":
            for c in range(3):
                for ph in range(patch_size):
                    for pw in range(patch_size):
                        val = 255 if (ph + pw) % 2 == 0 else 0
                        images[i, c, h_start + ph, w_start + pw] = val
        elif patch_type == "random":
            for c in range(3):
                patch = torch.randint(0, 256, (patch_size, patch_size))
                images[i, c, h_start:h_start+patch_size, w_start:w_start+patch_size] = patch
        else:
            for c in range(3):
                images[i, c, h_start:h_start+patch_size, w_start:w_start+patch_size] = patch_val

    return images.to(torch.uint8)

# Test all four corners with white patches
corners = ["tl", "tr", "bl", "br"]
patch_sizes = [3, 4, 5]

for ps in patch_sizes:
    print(f"\n=== Patch size {ps} ===")
    for corner in corners:
        imgs = create_patch_images("white", ps, corner)
